"const fs = require('fs');
const readline = require('readline');

async function processLineByLine() {
  const fileStream = fs.createReadStream('/Users/alex/Desktop/7_24bets-landing-page/scratch_user_inputs.jsonl');

  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  let output = '';

  for await (const line of rl) {
    try {
      const parsed = JSON.parse(line);
      const content = parsed.content || '';
      if (content.includes('groupedMatchesData') || content.includes('matchesData')) {
        output += `\n// --- FROM USER INPUT ---\n${content}\n`;
      }
    } catch (e) {
      console.error("Error parsing line", e);
    }
  }

  fs.writeFileSync('/Users/alex/Desktop/7_24bets-landing-page/extracted_matches_data.ts', output);
  console.log("Extracted matches data to extracted_matches_data.ts");
}

processLineByLine();"
